window.CARDS=window.CARDS||{};CARDS["story-v-y1v11-index"]=[{"i":"sc-ayanokouji-kiyotaka-y1v11-p7-1","v":"y1v11","y":1,"o":13,"k":"","w":"sakayanagi-arisu ayanokouji-kiyotaka","q":"ayanokoji kiyotaka prologue  seen in sakayanagi s memory in sakayanagi s childhood memory  a boy identified as ayanokoji kiyotaka calmly solves tasks and defeats opponents at chess in the white room  sakayanagi s father says he is the director s son and has lived in the facility since birth  this is recounted in sakayanagi s monologue  she observes him through glass during her childhood visit","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v11-p7-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v11-p7-1\">Prologue: Seen in Sakayanagi’s memory<\/a><\/span><span class=\"meta\">Y1V11 · p.7–12<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">In Sakayanagi’s childhood memory, a boy identified as Ayanokōji Kiyotaka calmly solves tasks and defeats opponents at chess in the White Room.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Sakayanagi’s father says he is the director’s son and has lived in the facility since birth; this is recounted in Sakayanagi’s monologue.<span class=\"pg\">p.10–11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> She observes him through glass during her childhood visit.<span class=\"pg\">p.10–12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v11-p27-1\">→ After: Ch.2: Event Selection Exam announced<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v11-p7-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka sakayanagi-arisu","q":"sakayanagi arisu prologue  white room memory in a childhood memory  visits a white facility with her father and watches children through one way glass  tells her father the experiment cannot create artificial geniuses because potential is set at birth  notices a boy calmly defeating opponents at chess  her father identifies him as ayanokoji kiyotaka  the director s son  hears from her father that kiyotaka has lived in the facility since birth and feels the loneliness of that life  recalls resolving to prove talent is not decided by education and to start playing chess  wakes in the present thinking of their approaching confrontation  first saw him as a child in the white room and has remembered him since","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v11-p7-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v11-p7-1\">Prologue: White Room memory<\/a><\/span><span class=\"meta\">Y1V11 · p.7–12<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">In a childhood memory, visits a white facility with her father and watches children through one-way glass. Tells her father the experiment cannot create artificial geniuses because potential is set at birth. Notices a boy calmly defeating opponents at chess; her father identifies him as Ayanokōji Kiyotaka, the director’s son. Hears from her father that Kiyotaka has lived in the facility since birth and feels the loneliness of that life. Recalls resolving to prove talent is not decided by education and to start playing chess; wakes in the present thinking of their approaching confrontation.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> First saw him as a child in the White Room and has remembered him since.<span class=\"pg\">p.10–12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v11-p62-1\">→ After: Ch.3: Commanders’ meeting<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y1v11-p13-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"mashima-tomonari chabashira-sae hoshinomiya-chie tsukishiro","q":"tsukishiro ch 1  staff meeting on the first years  exams as acting director  finishes explaining the first years  final special exam and a new system to the staff  invites questions and responds when mashima challenges the class vote s risk of expulsions  smiles and argues that students have always faced expulsion risk under the school s rules   a huge risk that there will be expulsions  is it  haven t the students had to fear expulsion during every special exam so far  the rules of this school state that receiving just one failing mark would result in expulsion  right  i don t think an ordinary high school would have such a strict system in place  dismisses mashima s objections as old fashioned and says the new system will focus on first years  states he was sent by a higher corporate body backed by the government and will not reconsider the provisional exam  ends the meeting after mentioning he is considering a cultural festival next year  overrules his protests against the class vote and new system  continues pressing after she tries to stop mashima  addresses the staff including her during the meeting","h":"<article class=\"card\" id=\"sc-tsukishiro-y1v11-p13-1\"><h3><span class=\"ttl\">Ch.1: Staff meeting on the first-years’ exams<\/span><span class=\"meta\">Y1V11 · p.13–20<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#tsukishiro\">Tsukishiro<\/a><\/span><\/h3><p class=\"setup\">As acting director, finishes explaining the first-years’ final special exam and a new system to the staff. Invites questions and responds when Mashima challenges the Class Vote’s risk of expulsions. Smiles and argues that students have always faced expulsion risk under the school’s rules. Dismisses Mashima’s objections as old-fashioned and says the new system will focus on first-years. States he was sent by a higher corporate body backed by the government and will not reconsider the provisional exam. Ends the meeting after mentioning he is considering a cultural festival next year.<\/p><p class=\"with\">with <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a> · <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “A huge risk that there will be expulsions, is it? Haven’t the students had to fear expulsion during every special exam so far? The rules of this school state that receiving just one failing mark would result in expulsion, right?…”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “A huge risk that there will be expulsions, is it? Haven’t the students had to fear expulsion during every special exam so far? The rules of this school state that receiving just one failing mark would result in expulsion, right? I don’t think an ordinary high school would have such a strict system in place.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Overrules his protests against the Class Vote and new system.<span class=\"pg\">p.14–19<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Continues pressing after she tries to stop Mashima.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Addresses the staff including her during the meeting.<span class=\"pg\">p.14<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-chabashira-sae-y1v11-p14-1","v":"y1v11","y":1,"o":13,"k":"","w":"mashima-tomonari hoshinomiya-chie tsukishiro chabashira-sae","q":"chabashira sae ch 1  after the staff meeting watches as mashima challenges acting director tsukishiro in the staff meeting  tells mashima that is enough when his resistance becomes futile  calls mashima and hoshinomiya aside in the hallway to discuss the upcoming exam  notes the 20 million private point override does not require class points this time but remains dissatisfied with tsukishiro s approach  warns hoshinomiya not to do anything reckless and denies fantasizing about reaching class a  rejects mashima s attempt to bring up the past and says personal feelings are irrelevant to the time passed  tells hoshinomiya to be careful and leaves for class c  stops his protests in the meeting and talks with him afterward  discusses the exam and their rivalry with her  is dissatisfied with his decisions","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v11-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v11-p14-1\">Ch.1: After the staff meeting<\/a><\/span><span class=\"meta\">Y1V11 · p.14–25<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Watches as Mashima challenges Acting Director Tsukishiro in the staff meeting. Tells Mashima that is enough when his resistance becomes futile. Calls Mashima and Hoshinomiya aside in the hallway to discuss the upcoming exam. Notes the 20 million private-point override does not require class points this time but remains dissatisfied with Tsukishiro’s approach. Warns Hoshinomiya not to do anything reckless and denies fantasizing about reaching Class A. Rejects Mashima’s attempt to bring up the past and says personal feelings are irrelevant to the time passed. Tells Hoshinomiya to be careful and leaves for Class C.<\/p><p class=\"with\">with <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a> · <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a> · <a href=\"../../../people/index.html#tsukishiro\">Tsukishiro<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Stops his protests in the meeting and talks with him afterward.<span class=\"pg\">p.18, 21–24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Discusses the exam and their rivalry with her.<span class=\"pg\">p.21–25<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is dissatisfied with his decisions.<span class=\"pg\">p.18, 22<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v11-p27-1\">→ After: Ch.2: Announcing the Event Selection Exam<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p14-1","v":"y1v11","y":1,"o":13,"k":"","w":"chabashira-sae mashima-tomonari tsukishiro hoshinomiya-chie","q":"hoshinomiya chie ch 1  after the staff meeting watches as mashima challenges acting director tsukishiro in the staff meeting  talks with chabashira and mashima in the hallway  saying it is depressing that someone will be expelled  suggests tsukishiro may be trying to remove teachers who oppose him  teases chabashira about closing the gap and presses her about reaching class a  insists with chabashira that she has not brought personal feelings into the exams  after chabashira leaves  tells mashima she has gotten over the past but chabashira has not  says she has ichinose on her side and will not go easy on chabashira if class c gets close  talks with her about the exam and their rivalry  talks with him after the meeting  suspects his actions may target opposing teachers","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hoshinomiya-chie.html#sc-hoshinomiya-chie-y1v11-p14-1\">Ch.1: After the staff meeting<\/a><\/span><span class=\"meta\">Y1V11 · p.14–26<\/span><span class=\"by\">notes on <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/span><\/h3><p class=\"setup\">Watches as Mashima challenges Acting Director Tsukishiro in the staff meeting. Talks with Chabashira and Mashima in the hallway, saying it is depressing that someone will be expelled. Suggests Tsukishiro may be trying to remove teachers who oppose him. Teases Chabashira about closing the gap and presses her about reaching Class A. Insists with Chabashira that she has not brought personal feelings into the exams. After Chabashira leaves, tells Mashima she has gotten over the past but Chabashira has not. Says she has Ichinose on her side and will not go easy on Chabashira if Class C gets close.<\/p><p class=\"with\">with <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a> · <a href=\"../../../people/index.html#tsukishiro\">Tsukishiro<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Talks with her about the exam and their rivalry.<span class=\"pg\">p.21–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Talks with him after the meeting.<span class=\"pg\">p.21–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Suspects his actions may target opposing teachers.<span class=\"pg\">p.22<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p67-1\">→ After: Ch.3: Commanders’ meeting<\/button><\/div><\/article>"},{"i":"sc-mashima-tomonari-y1v11-p14-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"tsukishiro chabashira-sae hoshinomiya-chie mashima-tomonari","q":"mashima tomonari ch 1  opposing the acting director breaks the silence in the staff meeting and questions acting director tsukishiro about the first years  exams  protests that the class vote creates a huge risk of expulsions and is inappropriate so soon after tsukishiro s appointment   forgive my rudeness  acting director  but you ve only just recently been appointed to your post at this school  although i understand you ve made this decision based on everything that has happened so far  i think it s somewhat inappropriate for us to do something that will force expulsions just because there haven t been any amongst the first years yet  argues the provisional exam is different from past policies and that expulsions should not be practically forced  asks tsukishiro to reconsider the provisional exam  but is shut down  listens as hoshinomiya and chabashira discuss the exam in the hallway  tries to mediate between chabashira and hoshinomiya over their past rivalry  warns hoshinomiya that class c is different this year  challenges his decision but fails to change it  speaks with her and hoshinomiya after the meeting  speaks with her after the meeting and warns her about class c","h":"<article class=\"card\" id=\"sc-mashima-tomonari-y1v11-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mashima-tomonari.html#sc-mashima-tomonari-y1v11-p14-1\">Ch.1: Opposing the acting director<\/a><\/span><span class=\"meta\">Y1V11 · p.14–26<\/span><span class=\"by\">notes on <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a><\/span><\/h3><p class=\"setup\">Breaks the silence in the staff meeting and questions Acting Director Tsukishiro about the first-years’ exams. Protests that the Class Vote creates a huge risk of expulsions and is inappropriate so soon after Tsukishiro’s appointment. Argues the provisional exam is different from past policies and that expulsions should not be practically forced. Asks Tsukishiro to reconsider the provisional exam, but is shut down. Listens as Hoshinomiya and Chabashira discuss the exam in the hallway. Tries to mediate between Chabashira and Hoshinomiya over their past rivalry. Warns Hoshinomiya that Class C is different this year.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#tsukishiro\">Tsukishiro<\/a> · <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mashima Tomonari<\/b> “Forgive my rudeness, Acting Director, but you’ve only just recently been appointed to your post at this school. Although I understand you’ve made this decision based on everything that has happened so far, I think it’s somewhat…”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Forgive my rudeness, Acting Director, but you’ve only just recently been appointed to your post at this school. Although I understand you’ve made this decision based on everything that has happened so far, I think it’s somewhat inappropriate for us to do something that will force expulsions just because there haven’t been any amongst the first-years yet.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Challenges his decision but fails to change it.<span class=\"pg\">p.14–19<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Speaks with her and Hoshinomiya after the meeting.<span class=\"pg\">p.21–24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Speaks with her after the meeting and warns her about Class C.<span class=\"pg\">p.21–26<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mashima-tomonari-y1v11-p62-1\">→ After: Ch.3: Explaining the commander system<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v11-p27-1","v":"y1v11","y":1,"o":13,"k":"","w":"horikita-suzune ike-kanji sudou-ken shinohara-satsuki chabashira-sae ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  event selection exam announced attends homeroom as chabashira announces the event selection exam after yamauchi s expulsion  receives photos of the event rule handout from horikita  ike and sudo question him about receiving 42 praise votes in the class poll  horikita explains sakayanagi s plan on his behalf  volunteers to become the class commander to clear suspicions and because he holds a protection point  horikita supports him taking the commander role despite objections  receives the rules from her and is defended and steered into the commander role by her  is questioned by him and later supported when he volunteers  is questioned by him about the praise votes  faces her objection to him becoming commander  hears her explain the event selection exam rules","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v11-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v11-p27-1\">Ch.2: Event Selection Exam announced<\/a><\/span><span class=\"meta\">Y1V11 · p.27–54<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Attends homeroom as Chabashira announces the Event Selection Exam after Yamauchi’s expulsion. Receives photos of the event-rule handout from Horikita. Ike and Sudō question him about receiving 42 praise votes in the Class Poll. Horikita explains Sakayanagi’s plan on his behalf. Volunteers to become the class commander to clear suspicions and because he holds a protection point. Horikita supports him taking the commander role despite objections.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Receives the rules from her and is defended and steered into the commander role by her.<span class=\"pg\">p.42, 47–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Is questioned by him and later supported when he volunteers.<span class=\"pg\">p.46–52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Is questioned by him about the praise votes.<span class=\"pg\">p.46–52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Faces her objection to him becoming commander.<span class=\"pg\">p.52–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Hears her explain the Event Selection Exam rules.<span class=\"pg\">p.27–41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v11-p7-1\">← Before: Prologue: Seen in Sakayanagi’s memory<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v11-p55-1\">→ After: Ch.3: Opponents and Kei’s visit<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v11-p27-1","v":"y1v11","y":1,"o":13,"k":"","w":"ike-kanji horikita-suzune chabashira-sae","q":"chabashira sae ch 2  announcing the event selection exam enters class c on march 8 to announce the final special exam  explains the event selection exam as a comprehensive competition between classes  uses white and yellow cards to show that the class must propose ten events  prompts ike to speak and takes his rock paper scissors example seriously  explains event rules must be fair  understandable  and include tiebreakers to prevent draws  outlines the exam schedule and says seven events will be randomly selected from the five chosen by each class  explains that a commander is required  can intervene in events  and will be expelled if the class loses  says the class matchups will be decided by raffle among commanders after school  warns that losing could drop class c back to class d and explains class point changes  encourages him to ask questions and uses his example  answers her questions about events  rules  and matchups","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v11-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v11-p27-1\">Ch.2: Announcing the Event Selection Exam<\/a><\/span><span class=\"meta\">Y1V11 · p.27–41<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Enters Class C on March 8 to announce the final special exam. Explains the Event Selection Exam as a comprehensive competition between classes. Uses white and yellow cards to show that the class must propose ten events. Prompts Ike to speak and takes his rock-paper-scissors example seriously. Explains event rules must be fair, understandable, and include tiebreakers to prevent draws. Outlines the exam schedule and says seven events will be randomly selected from the five chosen by each class. Explains that a commander is required, can intervene in events, and will be expelled if the class loses. Says the class matchups will be decided by raffle among commanders after school. Warns that losing could drop Class C back to Class D and explains class-point changes.<\/p><p class=\"with\">with <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Encourages him to ask questions and uses his example.<span class=\"pg\">p.29–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Answers her questions about events, rules, and matchups.<span class=\"pg\">p.33, 35, 38<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v11-p14-1\">← Before: Ch.1: After the staff meeting<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v11-p59-1\">→ After: Ch.3: Commanders’ meeting<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y1v11-p29-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"chabashira-sae ayanokouji-kiyotaka sudou-ken ike-kanji","q":"ike kanji ch 2  exam explanation and aftermath hesitates to interrupt chabashira but asks what she means by  events   n no  it s just  don t you get angry at us when we interrupt you while you re still talking  answers chabashira s question by saying he is good at rock paper scissors   i i guess i m pretty good at stuff like rock paper scissors  questions how ayanokoji ended up with 42 praise votes in the class poll   well  i dunno if i m unhappy with it  i really just don t get what happened is all  everyone s been wondering how ayanokoji ended up with the most praise votes  like  how d he even get 42 of  em  supports ayanokoji volunteering as commander so no one will be expelled  asks her questions during the exam explanation  questions his praise votes  then supports him as commander  raises concerns together about yamauchi and the votes","h":"<article class=\"card\" id=\"sc-ike-kanji-y1v11-p29-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y1v11-p29-1\">Ch.2: Exam explanation and aftermath<\/a><\/span><span class=\"meta\">Y1V11 · p.29–52<\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><p class=\"setup\">Hesitates to interrupt Chabashira but asks what she means by “events”. Answers Chabashira’s question by saying he is good at rock-paper-scissors. Questions how Ayanokōji ended up with 42 praise votes in the Class Poll. Supports Ayanokōji volunteering as commander so no one will be expelled.<\/p><p class=\"with\">with <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “N-no, it’s just… don’t you get angry at us when we interrupt you while you’re still talking?”<span class=\"pg\">p.29<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “I-I guess I’m pretty good at stuff like rock-paper-scissors?”<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “…Well, I dunno if I’m unhappy with it. I really just don’t get what happened is all. Everyone’s been wondering how Ayanokōji ended up with the most praise votes. Like, how’d he even get 42 of ‘em?”<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Asks her questions during the exam explanation.<span class=\"pg\">p.29–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Questions his praise votes, then supports him as commander.<span class=\"pg\">p.46–52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Raises concerns together about Yamauchi and the votes.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-horikita-suzune-y1v11-p33-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka sudou-ken ike-kanji shinohara-satsuki horikita-suzune","q":"horikita suzune ch 2  exam rules and commander decision asks whether the extra events are meant to mislead opponents and questions rules about participation and commanders  takes photos of the event rule handout and shares them with ayanokoji  comments that the exam favors classes whose events are selected on the day  explains to sudo and ike that sakayanagi likely targeted yamauchi and used ayanokoji for praise votes  says she takes responsibility for exposing yamauchi and refuses to blame ayanokoji  when ayanokoji volunteers as commander  horikita says she does not want the risk but supports ayanokoji taking the role  suggests the class arrange a meeting to prepare  taking initiative in hirata s place  shares the rules with him  defends him  and helps steer him into the commander role  explains sakayanagi s plan to him  explains the class poll outcome to him  responds to concerns about ayanokoji as commander","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v11-p33-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v11-p33-1\">Ch.2: Exam rules and commander decision<\/a><\/span><span class=\"meta\">Y1V11 · p.33–54<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Asks whether the extra events are meant to mislead opponents and questions rules about participation and commanders. Takes photos of the event-rule handout and shares them with Ayanokōji. Comments that the exam favors classes whose events are selected on the day. Explains to Sudō and Ike that Sakayanagi likely targeted Yamauchi and used Ayanokōji for praise votes. Says she takes responsibility for exposing Yamauchi and refuses to blame Ayanokōji. When Ayanokōji volunteers as commander, Horikita says she does not want the risk but supports Ayanokōji taking the role. Suggests the class arrange a meeting to prepare, taking initiative in Hirata’s place.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Shares the rules with him, defends him, and helps steer him into the commander role.<span class=\"pg\">p.42, 47–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Explains Sakayanagi’s plan to him.<span class=\"pg\">p.47–51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Explains the Class Poll outcome to him.<span class=\"pg\">p.47–51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Responds to concerns about Ayanokōji as commander.<span class=\"pg\">p.52–53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v11-p55-1\">→ After: Ch.3: Leading class preparation<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v11-p46-1","v":"y1v11","y":1,"o":13,"k":"","w":"horikita-suzune ayanokouji-kiyotaka hirata-yousuke","q":"hirata yosuke ch 2  withdrawn during the exam announcement remains motionless at his desk with his eyes downcast while the class discusses the new exam  does not take initiative in organizing the class  leaving horikita to step in  she takes initiative in his place  present as the class discusses his praise votes and commander role","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v11-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v11-p46-1\">Ch.2: Withdrawn during the exam announcement<\/a><\/span><span class=\"meta\">Y1V11 · p.46, 54<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Remains motionless at his desk with his eyes downcast while the class discusses the new exam. Does not take initiative in organizing the class, leaving Horikita to step in.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She takes initiative in his place.<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Present as the class discusses his praise votes and commander role.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v11-p55-1\">→ After: Ch.3: Absent from class preparation<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v11-p46-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"ayanokouji-kiyotaka horikita-suzune ike-kanji sudou-ken","q":"sudo ken ch 2  questioning the class poll result speaks up before the class discussion to ask about what happened in the previous exam  says he wants to hear from ayanokoji because they lost yamauchi   hold up  we want to hear it from ayanokoji  we lost a buddy  you know that right  struggles to accept horikita s explanation and suggests ayanokoji might have been chosen because he is incredible  is surprised when ayanokoji volunteers to be commander  wants an explanation from him and reacts to his volunteering  listens to her explanation of sakayanagi s plan  raises the issue together with him","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v11-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v11-p46-1\">Ch.2: Questioning the Class Poll result<\/a><\/span><span class=\"meta\">Y1V11 · p.46–52<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Speaks up before the class discussion to ask about what happened in the previous exam. Says he wants to hear from Ayanokōji because they lost Yamauchi. Struggles to accept Horikita’s explanation and suggests Ayanokōji might have been chosen because he is incredible. Is surprised when Ayanokōji volunteers to be commander.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Hold up. We want to hear it from Ayanokōji. We lost a buddy… You know that right?”<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Wants an explanation from him and reacts to his volunteering.<span class=\"pg\">p.46–52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Listens to her explanation of Sakayanagi’s plan.<span class=\"pg\">p.47–51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Raises the issue together with him.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-karuizawa-kei-y1v11-p49-1","v":"y1v11","y":1,"o":13,"k":"","w":"horikita-suzune ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 2  class discussion agrees with horikita s deduction that no one would give praise votes to a strong opponent  calls out horikita for covering for ayanokoji and then supporting him as commander  agrees with her reasoning  then questions her inconsistency  reacts to the discussion about him becoming commander","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v11-p49-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v11-p49-1\">Ch.2: Class discussion<\/a><\/span><span class=\"meta\">Y1V11 · p.49, 53<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Agrees with Horikita’s deduction that no one would give praise votes to a strong opponent. Calls out Horikita for covering for Ayanokōji and then supporting him as commander.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Agrees with her reasoning, then questions her inconsistency.<span class=\"pg\">p.49, 53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reacts to the discussion about him becoming commander.<span class=\"pg\">p.53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v11-p74-1\">→ After: Ch.3: Visiting Ayanokōji’s room<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v11-p49-1","v":"y1v11","y":1,"o":13,"k":"","w":"horikita-suzune ayanokouji-kiyotaka sakura-airi","q":"sakura airi ch 2  class discussion agrees with horikita s deduction that no one would give praise votes to a strong opponent  supports her explanation  participates in the discussion about his praise votes","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v11-p49-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v11-p49-1\">Ch.2: Class discussion<\/a><\/span><span class=\"meta\">Y1V11 · p.49<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Agrees with Horikita’s deduction that no one would give praise votes to a strong opponent.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Supports her explanation.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Participates in the discussion about his praise votes.<span class=\"pg\">p.49<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-shinohara-satsuki-y1v11-p52-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka horikita-suzune shinohara-satsuki","q":"shinohara satsuki ch 2  objecting to ayanokoji as commander objects to ayanokoji becoming commander  saying it could feel like giving up on winning and that he is only average  asks if anyone else is interested in taking the role instead  opposes him serving as commander  challenges her support for ayanokoji","h":"<article class=\"card\" id=\"sc-shinohara-satsuki-y1v11-p52-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shinohara-satsuki.html#sc-shinohara-satsuki-y1v11-p52-1\">Ch.2: Objecting to Ayanokōji as commander<\/a><\/span><span class=\"meta\">Y1V11 · p.52–53<\/span><span class=\"by\">notes on <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/span><\/h3><p class=\"setup\">Objects to Ayanokōji becoming commander, saying it could feel like giving up on winning and that he is only average. Asks if anyone else is interested in taking the role instead.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Opposes him serving as commander.<span class=\"pg\">p.52–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Challenges her support for Ayanokōji.<span class=\"pg\">p.52–53<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v11-p55-1","v":"y1v11","y":1,"o":13,"k":"","w":"chabashira-sae sakayanagi-arisu ichinose-honami kaneda-satoru karuizawa-kei ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  opponents and kei s visit leaves during lunch to contact others before returning to class c s meeting  leaves the classroom as commander and heads to the multipurpose room with chabashira  tells chabashira he volunteered to be commander  attends the commanders  meeting with sakayanagi  ichinose  and kaneda  kaneda chooses class b  leaving class c matched against class a  listens as the teachers explain the commander interface and rules for exam day  returns to his dorm thinking he needs information about class c and plans to consult others  invites kei into his room in the evening  asks kei about the internal state of the class and considers consulting hirata and kushida later  gives kei a necklace as a birthday and white day present  walks with her to the multipurpose room and discusses becoming commander  faces her as class c s commander when the matchup becomes class c vs class a  meets her at the commanders  meeting  present as he chooses class b  meets her in his room  gathers information  and gives her a necklace","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v11-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v11-p55-1\">Ch.3: Opponents and Kei’s visit<\/a><\/span><span class=\"meta\">Y1V11 · p.55–92<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Leaves during lunch to contact others before returning to Class C’s meeting. Leaves the classroom as commander and heads to the multipurpose room with Chabashira. Tells Chabashira he volunteered to be commander. Attends the commanders’ meeting with Sakayanagi, Ichinose, and Kaneda. Kaneda chooses Class B, leaving Class C matched against Class A. Listens as the teachers explain the commander interface and rules for exam day. Returns to his dorm thinking he needs information about Class C and plans to consult others. Invites Kei into his room in the evening. Asks Kei about the internal state of the class and considers consulting Hirata and Kushida later. Gives Kei a necklace as a birthday and White Day present.<\/p><p class=\"with\">with <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a> · <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Walks with her to the multipurpose room and discusses becoming commander.<span class=\"pg\">p.59–61<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Faces her as Class C’s commander when the matchup becomes Class C vs Class A.<span class=\"pg\">p.62–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Meets her at the commanders’ meeting.<span class=\"pg\">p.62–66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Present as he chooses Class B.<span class=\"pg\">p.62–66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Meets her in his room, gathers information, and gives her a necklace.<span class=\"pg\">p.74–92<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v11-p27-1\">← Before: Ch.2: Event Selection Exam announced<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v11-p55-1","v":"y1v11","y":1,"o":13,"k":"","w":"wang-mei-yu horikita-suzune hirata-yousuke","q":"hirata yosuke ch 3  absent from class preparation does not return for the class c meeting after lunch  leaves the classroom after school despite being called back  mii chan goes after him  she follows him when he leaves  takes over class leadership in his absence","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v11-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v11-p55-1\">Ch.3: Absent from class preparation<\/a><\/span><span class=\"meta\">Y1V11 · p.55–58<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Does not return for the Class C meeting after lunch. Leaves the classroom after school despite being called back; Mii-chan goes after him.<\/p><p class=\"with\">with <a href=\"../../../people/wang-mei-yu.html\">Wang Mei-Yu<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Wang Mei-Yu<\/b> She follows him when he leaves.<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Takes over class leadership in his absence.<span class=\"pg\">p.55, 58<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v11-p46-1\">← Before: Ch.2: Withdrawn during the exam announcement<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v11-p55-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka hirata-yousuke horikita-suzune","q":"horikita suzune ch 3  leading class preparation after lunch  most of class c gathers in the classroom to prepare for the event selection exam  distributes copies of the exam handout and tells classmates to read it and ask questions  prepares to lead the after school discussion in hirata s absence and tells ayanokoji to choose class d if given the choice  sends him to the commanders  meeting with instructions  notes his absence and takes initiative in his place","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v11-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v11-p55-1\">Ch.3: Leading class preparation<\/a><\/span><span class=\"meta\">Y1V11 · p.55–59<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">After lunch, most of Class C gathers in the classroom to prepare for the Event Selection Exam. Distributes copies of the exam handout and tells classmates to read it and ask questions. Prepares to lead the after-school discussion in Hirata’s absence and tells Ayanokōji to choose Class D if given the choice.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Sends him to the commanders’ meeting with instructions.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Notes his absence and takes initiative in his place.<span class=\"pg\">p.55, 58<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v11-p33-1\">← Before: Ch.2: Exam rules and commander decision<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y1v11-p55-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka kouenji-rokusuke","q":"koenji rokusuke ch 3  absent from class preparation does not return for the class c meeting after lunch  remains uninvolved after school  looking at his phone while classmates react to hirata s departure  is noted by him as someone who will not easily change","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y1v11-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y1v11-p55-1\">Ch.3: Absent from class preparation<\/a><\/span><span class=\"meta\">Y1V11 · p.55–58<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Does not return for the Class C meeting after lunch. Remains uninvolved after school, looking at his phone while classmates react to Hirata’s departure.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is noted by him as someone who will not easily change.<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-wang-mei-yu-y1v11-p58-1","v":"y1v11","y":1,"o":13,"k":"","w":"hirata-yousuke wang-mei-yu","q":"wang mei yu ch 3  chasing after hirata says she is going to the bathroom but leaves to chase after hirata when he exits the classroom  goes after him when he leaves","h":"<article class=\"card\" id=\"sc-wang-mei-yu-y1v11-p58-1\"><h3><span class=\"ttl\"><a href=\"../../../people/wang-mei-yu.html#sc-wang-mei-yu-y1v11-p58-1\">Ch.3: Chasing after Hirata<\/a><\/span><span class=\"meta\">Y1V11 · p.58<\/span><span class=\"by\">notes on <a href=\"../../../people/wang-mei-yu.html\">Wang Mei-Yu<\/a><\/span><\/h3><p class=\"setup\">Says she is going to the bathroom but leaves to chase after Hirata when he exits the classroom.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Goes after him when he leaves.<span class=\"pg\">p.58<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-chabashira-sae-y1v11-p59-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka mashima-tomonari chabashira-sae","q":"chabashira sae ch 3  commanders  meeting instructs the class to send the commander to the hallway and goes with ayanokoji to the special building  questions ayanokoji about volunteering as commander and warns him of the responsibility  attends the commanders  meeting and helps explain the exam day system  demonstrates the participant selection interface on the computer  accompanies him and oversees the commanders  meeting  explains the commander procedures together with him","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v11-p59-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v11-p59-1\">Ch.3: Commanders’ meeting<\/a><\/span><span class=\"meta\">Y1V11 · p.59–71<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Instructs the class to send the commander to the hallway and goes with Ayanokōji to the special building. Questions Ayanokōji about volunteering as commander and warns him of the responsibility. Attends the commanders’ meeting and helps explain the exam-day system. Demonstrates the participant-selection interface on the computer.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Accompanies him and oversees the commanders’ meeting.<span class=\"pg\">p.59–67<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Explains the commander procedures together with him.<span class=\"pg\">p.62–71<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v11-p27-1\">← Before: Ch.2: Announcing the Event Selection Exam<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v11-p62-1","v":"y1v11","y":1,"o":13,"k":"","w":"sakayanagi-arisu kaneda-satoru hoshinomiya-chie ayanokouji-kiyotaka ichinose-honami","q":"ichinose honami ch 3  commanders  meeting attends the commanders  meeting as class b s representative  draws first in the lottery at sakayanagi s suggestion  becomes the target when kaneda chooses class b as class d s opponent  reacts playfully with hoshinomiya to the event day interface demonstration  draws before her and is discussed as an opponent  is chosen by him as class b s opponent  reacts with her during the system explanation  meets him at the commanders  meeting","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v11-p62-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v11-p62-1\">Ch.3: Commanders’ meeting<\/a><\/span><span class=\"meta\">Y1V11 · p.62–67<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Attends the commanders’ meeting as Class B’s representative. Draws first in the lottery at Sakayanagi’s suggestion. Becomes the target when Kaneda chooses Class B as Class D’s opponent. Reacts playfully with Hoshinomiya to the event-day interface demonstration.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a> · <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Draws before her and is discussed as an opponent.<span class=\"pg\">p.62–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Is chosen by him as Class B’s opponent.<span class=\"pg\">p.64–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Reacts with her during the system explanation.<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him at the commanders’ meeting.<span class=\"pg\">p.62–66<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kaneda-satoru-y1v11-p62-1","v":"y1v11","y":1,"o":13,"k":"","w":"ichinose-honami sakayanagi-arisu ayanokouji-kiyotaka kaneda-satoru","q":"kaneda satoru ch 3  choosing class b attends the commanders  meeting as class d s representative  wins the lottery draw for the right to choose an opponent  chooses class b as class d s opponent  explains that class d wants to take points from an upper class while avoiding class a  selects her class as class d s opponent  answers her question about the choice  faces him at the commanders  meeting","h":"<article class=\"card\" id=\"sc-kaneda-satoru-y1v11-p62-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kaneda-satoru.html#sc-kaneda-satoru-y1v11-p62-1\">Ch.3: Choosing Class B<\/a><\/span><span class=\"meta\">Y1V11 · p.62–66<\/span><span class=\"by\">notes on <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/span><\/h3><p class=\"setup\">Attends the commanders’ meeting as Class D’s representative. Wins the lottery draw for the right to choose an opponent. Chooses Class B as Class D’s opponent. Explains that Class D wants to take points from an upper class while avoiding Class A.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Selects her class as Class D’s opponent.<span class=\"pg\">p.64–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Answers her question about the choice.<span class=\"pg\">p.64–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Faces him at the commanders’ meeting.<span class=\"pg\">p.62–66<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-mashima-tomonari-y1v11-p62-1","v":"y1v11","y":1,"o":13,"k":"","w":"kaneda-satoru chabashira-sae mashima-tomonari","q":"mashima tomonari ch 3  explaining the commander system runs the lottery to decide which commander may choose an opponent  confirms the lottery results and kaneda s right to choose  finalizes the matchups as class d vs class b and class c vs class a  explains the commander s exam day procedures  including participant selection and time limits  warns that improper interference can lead to disqualification and explains headset text to speech rules  confirms his choice of opponent  explains the system alongside her","h":"<article class=\"card\" id=\"sc-mashima-tomonari-y1v11-p62-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mashima-tomonari.html#sc-mashima-tomonari-y1v11-p62-1\">Ch.3: Explaining the commander system<\/a><\/span><span class=\"meta\">Y1V11 · p.62–71<\/span><span class=\"by\">notes on <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a><\/span><\/h3><p class=\"setup\">Runs the lottery to decide which commander may choose an opponent. Confirms the lottery results and Kaneda’s right to choose. Finalizes the matchups as Class D vs Class B and Class C vs Class A. Explains the commander’s exam-day procedures, including participant selection and time limits. Warns that improper interference can lead to disqualification and explains headset/text-to-speech rules.<\/p><p class=\"with\">with <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a> · <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Confirms his choice of opponent.<span class=\"pg\">p.63–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Explains the system alongside her.<span class=\"pg\">p.67–71<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mashima-tomonari-y1v11-p14-1\">← Before: Ch.1: Opposing the acting director<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v11-p62-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka ichinose-honami kaneda-satoru sakayanagi-arisu","q":"sakayanagi arisu ch 3  commanders  meeting attends the commanders  meeting as class a s representative  declines to draw first in the lottery and lets ichinose go ahead  comments that avoiding ichinose s class would be preferable  after kaneda chooses class b  says class a is saved from facing class b and wishes class d luck  faces him as commanders when class c is matched with class a  interacts with her during the lottery and matchup discussion  responds to his choice of class b","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v11-p62-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v11-p62-1\">Ch.3: Commanders’ meeting<\/a><\/span><span class=\"meta\">Y1V11 · p.62–65<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">Attends the commanders’ meeting as Class A’s representative. Declines to draw first in the lottery and lets Ichinose go ahead. Comments that avoiding Ichinose’s class would be preferable. After Kaneda chooses Class B, says Class A is saved from facing Class B and wishes Class D luck.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Faces him as commanders when Class C is matched with Class A.<span class=\"pg\">p.62–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Interacts with her during the lottery and matchup discussion.<span class=\"pg\">p.63–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Responds to his choice of Class B.<span class=\"pg\">p.64–65<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v11-p7-1\">← Before: Prologue: White Room memory<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p67-1","v":"y1v11","y":1,"o":13,"k":"","w":"ichinose-honami hoshinomiya-chie","q":"hoshinomiya chie ch 3  commanders  meeting attends the commanders  meeting and reacts playfully with ichinose during the interface demonstration  jokes with her during the explanation","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p67-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hoshinomiya-chie.html#sc-hoshinomiya-chie-y1v11-p67-1\">Ch.3: Commanders’ meeting<\/a><\/span><span class=\"meta\">Y1V11 · p.67<\/span><span class=\"by\">notes on <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/span><\/h3><p class=\"setup\">Attends the commanders’ meeting and reacts playfully with Ichinose during the interface demonstration.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Jokes with her during the explanation.<span class=\"pg\">p.67<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p14-1\">← Before: Ch.1: After the staff meeting<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v11-p74-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 3  visiting ayanokoji s room visits ayanokoji s dorm room in the evening after school  worries about being seen but is reassured that it is less necessary to hide now  questions why he became commander and says she would not have taken the role  shares information about the girls in class c and discusses hirata and kushida  asks ayanokoji to keep her from having to participate in events  receives a necklace from ayanokoji as a birthday and white day present   wh  what is this  criticises the gift choice but tries on the necklace and keeps it  visits him  provides class information  and receives a necklace","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v11-p74-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v11-p74-1\">Ch.3: Visiting Ayanokōji’s room<\/a><\/span><span class=\"meta\">Y1V11 · p.74–92<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Visits Ayanokōji’s dorm room in the evening after school. Worries about being seen but is reassured that it is less necessary to hide now. Questions why he became commander and says she would not have taken the role. Shares information about the girls in Class C and discusses Hirata and Kushida. Asks Ayanokōji to keep her from having to participate in events. Receives a necklace from Ayanokōji as a birthday and White Day present. Criticises the gift choice but tries on the necklace and keeps it.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “Wh… What is this!?”<span class=\"pg\">p.86<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Visits him, provides class information, and receives a necklace.<span class=\"pg\">p.74–92<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v11-p49-1\">← Before: Ch.2: Class discussion<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v11-p78-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka kushida-kikyou","q":"kushida kikyo ch 3  considered as a source of information ayanokoji considers consulting kushida later to learn about the class  while noting she may be wary after the class poll  kushida does not appear in person in this chapter  he considers asking her for information about the class","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v11-p78-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v11-p78-1\">Ch.3: Considered as a source of information<\/a><\/span><span class=\"meta\">Y1V11 · p.78<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Ayanokōji considers consulting Kushida later to learn about the class, while noting she may be wary after the Class Poll.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Kushida does not appear in person in this chapter.<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He considers asking her for information about the class.<span class=\"pg\">p.78<\/span><\/li><\/ul><\/details><\/article>"}];
